package questions

import (
	"bytes"
	"context"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// Golden bytes were generated by this same business mutation on f0aa82bb.
func baselineBusinessWrite(t *testing.T) *Service {
	t.Helper()
	s := New(filepath.Join(t.TempDir(), "questions"), nil)
	now := time.Date(2026, 10, 29, 12, 0, 0, 0, time.UTC)
	s.SetClock(func() time.Time { return now })
	if err := s.store.update(func(doc *document) error {
		doc.LastNumber = 10
		doc.asOf = now
		doc.Hourly = []hourlyMark{{At: now, RequesterHash: "business-hash"}}
		for i, channel := range []string{"console", "rule"} {
			doc.Questions = append(doc.Questions, Question{ID: "q_" + strings.Repeat(string(rune('a'+i)), 16), Number: i + 1,
				Status: StatusAnswered, Requester: "review", RequesterThread: "local_golden", CreatedAt: now, ExpiresAt: now.Add(time.Hour),
				Options: []Option{{Key: "a", Label: "Proceed"}}, Answer: &Answer{At: now, By: "owner", Channel: channel, Option: "a"}})
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	return s
}

func TestThreadInboxBusinessBytesMatchBaseline(t *testing.T) {
	t.Parallel()
	s := baselineBusinessWrite(t)
	want, err := os.ReadFile("testdata/thread_inbox_f0aa82bb.json")
	if err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 2; i++ {
		raw, err := os.ReadFile(s.store.path)
		if err != nil || !bytes.Equal(raw, want) {
			t.Fatalf("business bytes differ from f0aa82bb: %v\n%s", err, raw)
		}
		if bytes.Contains(raw, []byte("thread_inbox")) {
			t.Fatal("delivery metadata serialized")
		}
		if err := s.retryThreadInbox(context.Background(), func(context.Context, string, string, string) error { return nil }); err != nil {
			t.Fatal(err)
		}
	}
}

// Serial: replaces the process-wide diagnostic logger.
func TestThreadInboxBusinessPruningIsCounted(t *testing.T) {
	previous := slog.Default()
	var log bytes.Buffer
	slog.SetDefault(slog.New(slog.NewTextHandler(&log, nil)))
	t.Cleanup(func() { slog.SetDefault(previous) })

	s := New(filepath.Join(t.TempDir(), "questions"), nil)
	s.store.keepOverride, s.store.keep = true, 1
	if err := s.store.update(func(doc *document) error {
		doc.asOf = time.Now()
		for i := 0; i < 4; i++ {
			doc.Questions = append(doc.Questions, Question{ID: "q_" + strings.Repeat(string(rune('a'+i)), 16), Status: StatusWithdrawn})
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	if !bytes.Contains(log.Bytes(), []byte("question business records pruned")) || !bytes.Contains(log.Bytes(), []byte("count=3")) {
		t.Fatalf("pruning not counted: %s", log.String())
	}
}
